void Solver::bump_var(int var, double coeff) {
    // increase activity of the variable
    activity[var] += var_inc * coeff;

    // protect against overflow by rescaling all activities when a threshold is exceeded
    const double ACTIVITY_LIMIT = 1e150;
    if (activity[var] > ACTIVITY_LIMIT) {
        double scale = 1e-150;
        for (int i = 1; i <= vars; ++i) {
            activity[i] *= scale;
        }
        var_inc *= scale;
    }

    // keep the VSIDS heap consistent
    if (vsids.inHeap(var)) {
        vsids.update(var);
    } else {
        vsids.insert(var);
    }
}
